snippetModel.unrestricted:
switch (e.Key)
            {
                case Key.Home:
                    {
                        GotoSelectionBegin();
                        break;
                    }
                case Key.End:
                    {
                        GotoSelectionEnd();
                        break;
                    }
                case Key.PageDown:
                    {
                        GotoNextBookMark();
                        break;
                    }
                case Key.PageUp:
                    {
                        GotoPreviousBookMark();
                        break;
                    }
                case Key.Space:
                    {
                        if (videoPlayer.TimeSource.IsPlaying)
                            videoPlayer.TimeSource.Pause();
                        else
                            videoPlayer.TimeSource.Play();
                        break;
                    }
                case Key.Left:
                case Key.Right:
                    {
                        double multiplier = e.Key == Key.Right ? 1 : -1;

                        if (cckRtl.IsChecked == true)
                            multiplier *= -1;

                        if (control && shift)
                            ShiftTime(TimeSpan.FromMilliseconds(multiplier * 100));
                        else if (control)
                            ShiftTime(TimeSpan.FromMilliseconds(multiplier * 1000));
                        else if (shift)
                            ShiftTime(TimeSpan.FromMilliseconds(multiplier * 20));
                        else
                            ShiftTime(TimeFrameContext.TotalDisplayedDuration.Multiply(multiplier / 2.0));


                        break;
                    }
                case Key.B:
                {
                    Bump();
                    break;
                }
                case Key.C:
                    {
                        //if (shift)
                        //    EnforceCommonBeatDuration();
                        //else
                        //    FindCommonBeatDuration();
                        //break;
                        if (control)
                            CopyBeats();
                        break;
                    }
                case Key.D:
                {
                    StretchSelection();
                    break;
                }
                case Key.E:
                    {
                        EqualizeBeatLengths();
                        break;
                    }
                case Key.F:
                    {
                        Fade();
                        break;
                    }
                case Key.I:
                    {
                        Invert();
                        break;
                    }
                case Key.L:
                    {
                        Limit();
                        break;
                    }
                case Key.N:
                    {
                        Normalize();
                        break;
                    }
                case Key.O:
                    {
                        NormalizePattern();
                        break;
                    }
                case Key.P:
                    {
                        PatternFill();
                        break;
                    }
                case Key.Q:
                    {
                        ConvertToCustomPositions();
                        break;
                    }
                case Key.R:
                    {
                        ChangeRange();
                        break;
                    }
                case Key.S:
                    {
                        //For the lack of a better term :)
                        SuperNormalize(shift);
                        break;
                    }
                case Key.T:
                    {
                        FadeNormalize();
                        break;
                    }
                case Key.V:
                    {
                        if (control)
                            PasteBeats(shift);
                        break;
                    }
                case Key.Delete:
                    {
                        DeleteBeatsWithinMarkers();
                        break;
                    }
                case Key.Add:
                    {
                        if (control)
                        {
                            if (shift)
                                NormalizePattern(pattern, patternBeats);
                            else
                                NormalizePattern(pattern, 1);
                        }
                        else
                            Normalize(1, !caps);
                        break;
                    }
                case Key.Subtract:
                    {
                        if (control)
                        {
                            if (shift)
                                NormalizePattern(pattern, -patternBeats);
                            else
                                NormalizePattern(pattern, -1);
                        }
                        else
                            Normalize(-1, !caps);
                        break;
                    }
                case Key.F3:
                    {
                        FindShortestBeatLongerThanPrevious();
                        break;
                    }
                case Key.F5:
                    {
                        JumpToFirst();
                        break;
                    }
                case Key.F6:
                    {
                        SnapToClosestBeat();
                        break;
                    }
                case Key.F7:
                    {
                        JumpToShortest();
                        break;
                    }
                case Key.F8:
                    {
                        JumpToLast();
                        break;
                    }
                case Key.Enter:
                    {
                        if (IsNumpadEnterKey(e))
                        {
                            if (control)
                                NormalizePattern(_previousPattern ?? new bool[] { true, true }, 0);
                            else
                                Normalize(0, !caps);
                        }
                        else
                        {
                            handled = false;
                        }
                        break;
                    }
                case Key.NumPad1:
                    {
                        AddPositionNow(0);
                        break;
                    }
                case Key.NumPad2:
                    {
                        AddPositionNow(50);
                        break;
                    }
                case Key.NumPad3:
                    {
                        AddPositionNow(99);
                        break;
                    }
                default:
                    handled = false;
                    break;
            }

